                vyvesit() {
                    if (this.data) {
                        if (this.data.s_ude == 0) { // Zkontroluji zda je záznam ve stavu návrh
                            var dateTo = this.findForms("formDetailVyveseni").findFields("dat_do").gfield("getValue");
                            var dateFrom = this.findForms("formDetailVyveseni").findFields("dat_od").gfield("getValue");
                            var currentDate = new Date();
                            if (currentDate > dateTo && dateTo != null) {
                                this.dialogs.warning("jres:33000054", "jres:33000056".format(Gordic.Templates.Formatters.datetime(new Date(), "date"))); //RC 33000056 : Datum sejmutí musí být minimálně stejné jako dnešní datum {0}.
                            }
                            else if (dateFrom > currentDate) {
                                this.dialogs.confirm("jres:33000057", "jres:33000058".format(Math.ceil(Math.abs(dateFrom - currentDate) / (1000 * 60 * 60 * 24)), Gordic.Templates.Formatters.date(new Date(dateFrom), "date"))).on("yes", () => {
                                    this.vyvesitAct(true);
                                });
                            }
                            else {
                                this.vyvesitAct(false);
                            }
                        }
                        else {
                            this.dialogs.error("jres:33000054", "jres:33000055"); //RC 33000055 : Záznam není ve stavu návrh!
                        }
                    }
                }
