                    if (form.gform("isValid")) {
                        var from = cnt.findFields("dat_od").gfield("getValue");
                        var to = cnt.findFields("dat_do").gfield("getValue");
                        var currentDate = new Date();
                        if (currentDate > to && to != null)
                            this.dialogs.warning("jres:33000054", "jres:33000056".format(Gordic.Templates.Formatters.datetime(new Date(), "date"))); //RC 33000056 : Datum sejmutí musí být minimálně stejné jako dnešní datum {0}.
                        else if (from > currentDate && navrh == false) {
                            this.dialogs.confirm("jres:33000057", "jres:33000058".format(Math.ceil(Math.abs(from - currentDate) / (1000 * 60 * 60 * 24)), Gordic.Templates.Formatters.date(new Date(from), "date"))).on("yes", () => {
                                this.znovuVyvesitAct(true, navrh, from, to);
                            });
                        }
                        else
                            this.znovuVyvesitAct(false, navrh, from, to);
                        cnt.close();
                    }
