                            notif.state = "success";
                            notif.content = (o.vysledek == 0 /* Gordic.Uda.Interface.VysledekEnum.OK */) ? ((ulozitJakoNavrh == false) ? "jres:33000211" : "jres:33000230") : o.vysledekTxt?.toString(); //RC 33000230 : Návrh byl úspěšně uložen.
