                updateInsertSource(newSource) {
                    var currentSource = this.findForms("formDetailVyveseni").findFields("ixs_zud").gfield("getValue");
                    var form = new Gordic.Forms.Form({ name: "formEditSource", layoutDescriptor: "L1M1S1, L-2-10-0, M-2-10-0" })
                        .addRow("jres:24450016").addField("gstringbox", {
                        name: "nazev",
                        validators: [new Gordic.Validators.Required({ stopping: true })],
                        initialValue: (newSource == true) ? "" : currentSource.nazev
                    })
                        .addRow().addField("gdummyfield", {
                        name: "ixs_zud",
                        initialValue: (newSource == true) ? null : currentSource.ixs_zud,
                    });
                    this.dialogs.simpleForm((newSource == true) ? "jres:33000077" : "jres:33000078", form, {}, {
                        height: 230,
                        width: 450,
                        commandBar: [
                            {
                                primary: true,
                                action: this.actions.actSaveSource,
                            },
                            {
                                action: this.actions.actCancelDialog,
                            }
                        ]
                    });
                }
                saveSource(ev) {
                    var cnt = $.content(ev.target);
                    var form = cnt.findForms("formEditSource");
                    if (form.gform("isValid")) {
                        var nazev = form.findFields("nazev").gfield("getValue");
                        var ixs_zud = form.findFields("ixs_zud").gfield("getValue");
                        this.beginOperation();
                        Gordic.Isl.UdaZdroje.upsert({ ixs_zud: ixs_zud, nazev: nazev }).get().done((o) => {
                            this.notification("showToast", {
                                icon: "fa-check-circle",
                                state: "success",
                                title: "jres:33000079", //RC 33000079 : Zdroj pro úřední desku
                                content: "jres:33000080" //RC 33000080 : Záznam byl úspěšně uložen.
                            });
                            var field = this.findForms("formDetailVyveseni").findFields("ixs_zud");
                            new Gordic.Data.Readers.Udeszud().getData({ aktivita: 100 }).then((data) => {
                                field.gfield("option", "data", data);
                            }).then(() => {
                                new Gordic.Data.Readers.Udeszud().getData({ ixs_zud: o.data.ixs_zud }).done((source) => {
                                    if (source.length > 0)
                                        field.gfield("setValue", source[0]);
                                });
                            });
                            cnt.close();
                        }).fail(() => {
                            this.notification("add", {
                                icon: "fa-times-circle",
                                state: "error",
                                title: "jres:33000079", //RC 33000079 : Zdroj pro úřední desku
                                content: "jres:33000081" //RC 33000081 : Uložení neproběhlo správně.
                            });
                        }).always(() => { this.endOperation(); });
                    }
                }
                deleleZdroj() {
                    var zdrojUD = this.findForms("formDetailVyveseni").findFields("ixs_zud").gfield("getValue");
                    if (zdrojUD != null) {
                        this.dialogs.confirm("jres:33000083", "jres:33000084".format(zdrojUD.nazev)).on("yes", () => {
                            this.beginOperation();
                            Gordic.Isl.UdaZdroje.delete({ nazev: zdrojUD.nazev, ixs_zud: zdrojUD.ixs_zud }).get().done((o) => {
                                this.notification("showToast", {
                                    icon: "fa-check-circle",
                                    state: "success",
                                    title: "jres:33000079", //RC 33000079 : Zdroj pro úřední desku
                                    content: "jres:33000085" //RC 33000085 : Záznam byl úspěšně zneaktivněn.
                                });
                                var field = this.findForms("formDetailVyveseni").findFields("ixs_zud");
                                new Gordic.Data.Readers.Udeszud().getData({ aktivita: 100 }).then((data) => {
                                    field.gfield("option", "data", data);
                                    if (data.length > 0)
                                        field.gfield("setValue", data[0]);
                                });
                            }).fail(() => {
                                this.notification("add", {
                                    icon: "fa-times-circle",
                                    state: "error",
                                    title: "jres:33000079", //RC 33000079 : Zdroj pro úřední desku
                                    content: "jres:33000081" //RC 33000081 : Uložení neproběhlo správně.
                                });
                            }).always(() => { this.endOperation(); });
                        });
                    }
                }
