                addToFavorites() {
                    if (this.globalSettings) {
                        var gridSelStr = [];
                        var selection = this.grid.ggrid("getSelection");
                        selection.forEach((item) => {
                            var itemTmp = { ixs_ulo: item.ixs_ulo, por_cislo: item.por_cislo, ixs_ulz: item.ixs_ulz };
                            gridSelStr.push(JSON.stringify(itemTmp));
                        });
                        var favoriteOld = this.globalSettings.getDef(this.path, []);
                        var favoriteOldStr = [];
                        favoriteOld.forEach((item) => { favoriteOldStr.push(JSON.stringify(item)); });
                        var invalidAdd = 0;
                        var newData = [];
                        for (var j = 0; j < gridSelStr.length; j++) {
                            if (favoriteOldStr.length > 0) {
                                for (var i = 0; i < favoriteOldStr.length; i++) {
                                    if (gridSelStr[j] == favoriteOldStr[i]) {
                                        invalidAdd++;
                                        break;
                                    }
                                    if (i == favoriteOldStr.length - 1)
                                        newData.push({ ixs_ulo: selection[j].ixs_ulo, por_cislo: selection[j].por_cislo, ixs_ulz: selection[j].ixs_ulz });
                                }
                            }
                            else {
                                newData.push({ ixs_ulo: selection[j].ixs_ulo, por_cislo: selection[j].por_cislo, ixs_ulz: selection[j].ixs_ulz });
                            }
                        }
                        for (var i = 0; i < newData.length; i++) {
                            favoriteOld.push(newData[i]);
                        }
                        this.globalSettings.set(this.path, favoriteOld);
                        this.notification("add", {
                            icon: "gi-index",
                            title: this.headerCaption(),
                            content: "jres:33000152".format(newData.length, invalidAdd), //RC 33000152 : Počet úspěšně přidaných položek do oblíbených: {0}<br>Počet úspěšně přidaných položek do oblíbených: {1}
                            state: "info"
                        });
                        this.loadFavorites();
                        this.loadData();
                    }
                    else {
                        this.notification("add", {
                            icon: "gi-index",
                            title: this.headerCaption(),
                            content: "jres:33000153", //RC 33000153 : Přidání položek do oblíbených se nezdařilo.
                            state: "error"
                        });
                    }
                }
